        if (utf8proc_codepoint_valid(c))
            cstr[utf8proc_encode_char(c, cstr)] = 0;
        else
            strcat((char*)cstr, "N/A");
        utf8proc_map(cstr, 0, &map, UTF8PROC_NULLTERM | UTF8PROC_CASEFOLD);

        printf("U+%s: %s\n"
            "  category = %s\n"
            "  combining_class = %d\n"
            "  bidi_class = %d\n"
            "  decomp_type = %d\n"
            "  uppercase_mapping = %04x (seqindex %04x)%s\n"
